-- AI set, 0000_init: a fresh baseline for the ai context (conversations, messages, usage).
-- Generated by drizzle-kit, then hand-edited into the sharding design's order (§4 items 2 and 6):
-- per table CREATE -> distribution -> indexes, then RLS -> grants -> policies. One statement each:
-- with local execution off, Citus builds the shards over new connections.
-- Distribution: all three tables are distributed by tenant_id, colocated with
-- app.tenant_colocation (and so with every other tenant table). The platform helper is a no-op
-- without Citus and on a re-run. No FK: conversation_id and message_id are plain columns.
-- Hand-edited to IF NOT EXISTS: the drizzle migrator creates this schema first, for ai.__drizzle_migrations.
CREATE SCHEMA IF NOT EXISTS "ai";
--> statement-breakpoint
CREATE TYPE "ai"."message_role" AS ENUM('system', 'user', 'assistant', 'tool');--> statement-breakpoint
CREATE TYPE "ai"."message_status" AS ENUM('complete', 'incomplete');--> statement-breakpoint
CREATE TYPE "ai"."usage_outcome" AS ENUM('success', 'error', 'timeout', 'aborted');--> statement-breakpoint
CREATE TABLE "ai"."conversations" (
	"tenant_id" uuid NOT NULL,
	"id" uuid DEFAULT uuidv7() NOT NULL,
	"user_id" uuid NOT NULL,
	"title" text,
	"model" text NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "conversations_tenant_id_id_pk" PRIMARY KEY("tenant_id","id")
);
--> statement-breakpoint
SELECT app.distribute_by_tenant('ai.conversations');--> statement-breakpoint
CREATE INDEX "conversations_tenant_id_user_id_id_idx" ON "ai"."conversations" USING btree ("tenant_id","user_id","id");--> statement-breakpoint
CREATE TABLE "ai"."messages" (
	"tenant_id" uuid NOT NULL,
	"id" uuid DEFAULT uuidv7() NOT NULL,
	"conversation_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"role" "ai"."message_role" NOT NULL,
	"content" jsonb NOT NULL,
	"status" "ai"."message_status" DEFAULT 'complete' NOT NULL,
	"model" text,
	"input_tokens" integer,
	"output_tokens" integer,
	"idempotency_key" text,
	"request_hash" text,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "messages_tenant_id_id_pk" PRIMARY KEY("tenant_id","id")
);
--> statement-breakpoint
SELECT app.distribute_by_tenant('ai.messages');--> statement-breakpoint
CREATE INDEX "messages_tenant_id_conversation_id_id_idx" ON "ai"."messages" USING btree ("tenant_id","conversation_id","id");--> statement-breakpoint
CREATE UNIQUE INDEX "messages_tenant_id_conversation_id_idempotency_key_uq" ON "ai"."messages" USING btree ("tenant_id","conversation_id","idempotency_key");--> statement-breakpoint
CREATE TABLE "ai"."usage" (
	"tenant_id" uuid NOT NULL,
	"id" uuid DEFAULT uuidv7() NOT NULL,
	"user_id" uuid NOT NULL,
	"conversation_id" uuid NOT NULL,
	"message_id" uuid,
	"model" text NOT NULL,
	"input_tokens" integer DEFAULT 0 NOT NULL,
	"output_tokens" integer DEFAULT 0 NOT NULL,
	"cost_usd" numeric(14, 8),
	"latency_ms" integer NOT NULL,
	"outcome" "ai"."usage_outcome" NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "usage_tenant_id_id_pk" PRIMARY KEY("tenant_id","id")
);
--> statement-breakpoint
SELECT app.distribute_by_tenant('ai.usage');--> statement-breakpoint
CREATE INDEX "usage_tenant_id_user_id_id_idx" ON "ai"."usage" USING btree ("tenant_id","user_id","id");--> statement-breakpoint
-- Row-level security (program spec 8.2, sharding design 7.1): enabled and forced on every ai table,
-- so the owner (app_owner, no policy) reads and writes no row either. ai.__drizzle_migrations gets
-- no RLS and no grant to either app role.
ALTER TABLE ai.conversations ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE ai.conversations FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE ai.messages ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE ai.messages FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE ai.usage ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE ai.usage FORCE ROW LEVEL SECURITY;--> statement-breakpoint
-- Grants: deny by default, one table (or schema) to one role per statement, no default privileges,
-- so a table added later is unreachable until its own migration grants it. USAGE only: the runtime
-- role creates nothing in schema ai. app_system gets nothing: the ai context has no system method.
-- Messages are written once (no UPDATE); usage is append-only (no UPDATE, no DELETE).
GRANT USAGE ON SCHEMA ai TO app_runtime;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE ai.conversations TO app_runtime;--> statement-breakpoint
GRANT SELECT, INSERT, DELETE ON TABLE ai.messages TO app_runtime;--> statement-breakpoint
GRANT SELECT, INSERT ON TABLE ai.usage TO app_runtime;--> statement-breakpoint
-- Policies: row-local, calling the platform helpers (platform 0002_rls_helpers) directly, never
-- through a subquery (Citus rejects them). Every row belongs to one user in one tenant: messages and
-- usage carry the conversation owner's user_id, so no policy reads ai.conversations. Elevation
-- grants nothing here: nobody else reads a user's conversations. Rows of PLATFORM_TENANT_ID match no
-- policy (app.tenant_id() is never the nil UUID).
CREATE POLICY conversations_select ON ai.conversations FOR SELECT TO app_runtime
  USING (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY conversations_insert ON ai.conversations FOR INSERT TO app_runtime
  WITH CHECK (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY conversations_update ON ai.conversations FOR UPDATE TO app_runtime
  USING (tenant_id = app.tenant_id() AND user_id = app.user_id())
  WITH CHECK (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY conversations_delete ON ai.conversations FOR DELETE TO app_runtime
  USING (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY messages_select ON ai.messages FOR SELECT TO app_runtime
  USING (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY messages_insert ON ai.messages FOR INSERT TO app_runtime
  WITH CHECK (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY messages_delete ON ai.messages FOR DELETE TO app_runtime
  USING (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY usage_select ON ai.usage FOR SELECT TO app_runtime
  USING (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY usage_insert ON ai.usage FOR INSERT TO app_runtime
  WITH CHECK (tenant_id = app.tenant_id() AND user_id = app.user_id());
